399: void CALLBACK OnFrameMove( double fTime, float fElapsedTime, void* pUserContext )
400: {
401:     // Update the camera's position based on user input 
402:     g_Camera.FrameMove( fElapsedTime );
403: 
404:     // Set up the vertex shader constants
405:     D3DXMATRIXA16 mWorldViewProj;
406:     D3DXMATRIXA16 mWorld;
407:     D3DXMATRIXA16 mView;
408:     D3DXMATRIXA16 mProj;
409: 
410:     mWorld = *g_Camera.GetWorldMatrix();
411:     mView = *g_Camera.GetViewMatrix();
412:     mProj = *g_Camera.GetProjMatrix();
413: 
414:     mWorldViewProj = mWorld * mView * mProj;
415: 
416:     g_pConstantTable->SetMatrix( DXUTGetD3D9Device(), "mWorldViewProj", &mWorldViewProj );

438: 
439:     // Clear the render target and the zbuffer 
440:     V( pd3dDevice->Clear( 0, NULL, D3DCLEAR_TARGET | D3DCLEAR_ZBUFFER, D3DCOLOR_ARGB( 0, 45, 50, 170 ), 1.0f, 0 ) );
441: 
442:     // Render the scene
443:     if( SUCCEEDED( pd3dDevice->BeginScene() ) )
444:     {
445:         pd3dDevice->SetVertexDeclaration( g_pVertexDeclaration );
446:         pd3dDevice->SetVertexShader( g_pVertexShader );
447:         pd3dDevice->SetStreamSource( 0, g_pVB, 0, sizeof( D3DXVECTOR2 ) );
448:         pd3dDevice->SetIndices( g_pIB );
449: 
450:         V( pd3dDevice->DrawIndexedPrimitive( D3DPT_TRIANGLELIST, 0, 0, g_dwNumVertices,
451:                                              0, g_dwNumIndices / 3 ) );
452: 
453:         RenderText();
454:         V( g_HUD.OnRender( fElapsedTime ) );
455: 
456:         V( pd3dDevice->EndScene() );
457:     }
458: }

